#include "rftd2_private.h"
#include "cmd.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static const Cmd_Array1 cmd_array[] = 
{
    { INPUT_IGNITION  | INPUT_ON ,  rftd2_dtc_alert_update_ign_on  } , 
    { INPUT_IGNITION             ,  rftd2_dtc_alert_update_ign_off } , 
    { INPUT_DTC_ALERT | INPUT_ON ,  rftd2_dtc_alert_on     } ,
    { INPUT_DTC_ALERT            ,  rftd2_dtc_alert_off    } 
}; 
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void rftd2_init (void)
{
  	if(!rftd2_init_nvfs())
      {
        // error ?
      }
	CMD_LUT_INSERT1( cmd_array , EXEC_MODE_NORMAL );
	
}


